 422:         bool isAssignmentStmt() const {
 423:             std::size_t pos = cur_pos;
 424:             if (pos >= token_size ||
 425:                 tokens[pos].getType() != TokenType::IDENFR) {
 426:                 return false;
 427:                 }
 428:             ++pos;
 429:             if (pos < token_size &&
 430:                 tokens[pos].getType() == TokenType::LBRACK) {
 431:                 int bracketDepth = 1;
 432:                 ++pos;
 433:                 while (pos < token_size && bracketDepth > 0) {
 434:                     TokenType type = tokens[pos].getType();
 435: 
 436:                     if (type == TokenType::LBRACK) {
 437:                         ++bracketDepth;
 438:                     } else if (type == TokenType::RBRACK) {
 439:                         --bracketDepth;
 440:                     }
 441:                     ++pos;
 442:                 }
 443:                 if (bracketDepth != 0) {
 444:                     return false;
 445:                 }
 446:                 }
 447:             return pos < token_size &&
 448:                    tokens[pos].getType() == TokenType::ASSIGN;
 449:         }
